    "explanation": "1. CONCEPT:\nMarkovnikov addition with carbocation stability.\n\n2. GIVEN:\n(CH3)2C=CH-CH3 + HBr.\n\n3. FORMULA / PRINCIPLE:\nProtonation yields the tertiary carbocation (CH3)2C+-CH2CH3, followed by bromide capture.\n\n4. STEP-BY-STEP SOLUTION:\n1. The alkene is unsymmetrical: (CH3)2C=CH-CH3.\n2. Protonation at C-3 generates a stable tertiary carbocation: (CH3)2C+-CH2CH3.\n3. Protonation at C-2 would generate a less stable secondary carbocation: (CH3)2CH-CH+-CH3.\n4. Attack of Br- on the 3\u00b0 carbocation gives 2-bromo-2-methylbutane as the exclusive major product.\n\n5. FINAL ANSWER:\nOption A: 2-Bromo-2-methylbutane\n\n6. WHY OTHER OPTIONS ARE WRONG:\nThe tertiary carbocation is formed much faster than the secondary carbocation, directing bromine to C-2.",
