    "explanation": "1. CONCEPT:\nReactivity-selectivity principle in free radical halogenation.\n\n2. GIVEN:\nHydrogen abstraction step: RH + X. -> R. + HX.\n\n3. FORMULA / PRINCIPLE:\nBromination is endothermic (Delta H > 0), so transition state resembles the alkyl radical (Hammond's postulate), magnifying stability differences (3\u00b0 >> 2\u00b0 >> 1\u00b0).\n\n4. STEP-BY-STEP SOLUTION:\n1. Hydrogen abstraction by bromine radical is endothermic, requiring significant activation energy (Ea).\n2. According to Hammond's postulate, the transition state for an endothermic step late-stage resembles the products (the alkyl radical).\n3. Therefore, differences in radical stability (3\u00b0 is much more stable than 1\u00b0) are fully expressed in the transition state, leading to a 3\u00b0:1\u00b0 selectivity ratio of 1600 : 1 for bromine.\n4. Chlorination is exothermic; its early transition state resembles reactants, giving low selectivity (3\u00b0:1\u00b0 is only 5 : 1).\n\n5. FINAL ANSWER:\nOption A: The reactivity-selectivity principle (bromine radical is endothermic and highly selective for 3\u00b0 C-H)\n\n6. WHY OTHER OPTIONS ARE WRONG:\nBromine's low reactivity makes it exceptionally selective for tertiary C-H bonds compared to unselective chlorine.",
